import{_ as n,o as r,c as t,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-stundentafeln-zuweisen.png",c=JSON.parse('{"title":"Stundentafeln einer Schülergruppe zuweisen","description":"","frontmatter":{"title":"Stundentafeln einer Schülergruppe zuweisen","source_pageid":297,"source_revision":5342},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/stundentafeln-zuweisen-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/stundentafeln-zuweisen-gruppenprozesse-faecher.md"}'),i={name:"schild3/suchen-gruppenprozesse/stundentafeln-zuweisen-gruppenprozesse-faecher.md"};function u(l,e,d,h,o,g){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="stundentafeln-einer-schulergruppe-zuweisen" tabindex="-1">Stundentafeln einer Schülergruppe zuweisen <a class="header-anchor" href="#stundentafeln-einer-schulergruppe-zuweisen" aria-label="Permalink to &quot;Stundentafeln einer Schülergruppe zuweisen&quot;">​</a></h1><p>Übernehmen Sie vorbereitete Stundentafeln in die Leistungsdaten der ausgewählten Schülergruppe. Prüfen Sie Fächerauswahl und die unterschiedlichen Optionen zum Ergänzen oder Löschen.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-stundentafeln-zuweisen.png"><img src="'+a+'" alt="Der Gruppenprozess Stundentafeln zuweisen dient dazu, definierte Stundentafeln jahrgangs- oder klassenweise zuzuweisen." loading="lazy"></a></p><p><em>Der Gruppenprozess <strong>Stundentafeln zuweisen</strong> dient dazu, definierte Stundentafeln jahrgangs- oder klassenweise zuzuweisen.</em></p><h2 id="_1-die-stundentafel-und-facher-wahlen" tabindex="-1">1. Die Stundentafel und Fächer wählen <a class="header-anchor" href="#_1-die-stundentafel-und-facher-wahlen" aria-label="Permalink to &quot;1. Die Stundentafel und Fächer wählen&quot;">​</a></h2><p>Mit dem Aufruf des Gruppenprozesses <strong>Stundentafeln zuweisen</strong> erscheint das Eingabefenster <em>Stundentafel auswählen</em>.</p><p>Die bereits unter <strong>Kataloge/Stundentafeln</strong> angelegten Stundentafeln für die einzelnen Jahrgänge werden hier aufgelistet.</p><p>Durch das Klicken auf das <strong>+</strong> in der Spalte Jahrgang werden die Fächer, die der aktuell ausgewählten Stundentafel zugeordnet wurden, angezeigt.</p><p>Jedes in der Stundentafel vermerkte Fach ist ausgewählt.</p><p>Sollten ein oder mehrere Fächer in diesem Schul(halb)jahr nicht unterrichtet werden, können die entsprechenden Haken entfernt werden und die bestimmten Fächer werden nicht übernommen.</p><h2 id="_2-erganzen-oder-loschen-festlegen" tabindex="-1">2. Ergänzen oder Löschen festlegen <a class="header-anchor" href="#_2-erganzen-oder-loschen-festlegen" aria-label="Permalink to &quot;2. Ergänzen oder Löschen festlegen&quot;">​</a></h2><p>Mit <strong>vorhandene Einträge beim Schüler aktualisieren</strong> übernehmen Sie die Vorgaben der Stundentafel für die angehakten Fächer in das aktuelle Halbjahr der ausgewählten Schülerinnen und Schüler:</p><ul><li>Bei einem bereits vorhandenen Fach werden <strong>Kursart</strong>, <strong>Wochenzeiteinheit (WZE)</strong> und der Haken <strong>Epochenunterricht</strong> an die Stundentafel angepasst. Eine bereits eingetragene <strong>Note bleibt erhalten</strong>.</li><li>Ein noch nicht vorhandenes Fach wird neu angelegt.</li></ul><p>Die zugeordnete <strong>Lehrkraft bleibt unverändert</strong>. Die Stundentafel-Aktualisierung ändert die Lehrkraftzuordnung nicht. Kontrollieren Sie nach der Zuweisung die Fachbelegungen und die übernommenen Angaben.</p><p>Nicht mit einem Häkchen versehene Fächer werden nicht gelöscht.</p><p><strong>Achtung: Ein ausgewähltes Fach wird auch dann gelöscht, wenn bereits eine Note eingetragen ist.</strong></p><p>Mit <strong>ausgewählte Fächer beim Schüler löschen</strong> entfernen Sie die angehakten Fächer bei der ausgewählten Schülergruppe. Lassen Sie nur die Häkchen der Fächer gesetzt, die tatsächlich gelöscht werden sollen.</p><h2 id="_3-die-zuweisung-ubernehmen" tabindex="-1">3. Die Zuweisung übernehmen <a class="header-anchor" href="#_3-die-zuweisung-ubernehmen" aria-label="Permalink to &quot;3. Die Zuweisung übernehmen&quot;">​</a></h2><p>Die gewählten Fächer werden je nach Einstellung mit einem Mausklick auf <code>Übernehmen</code> bei den Schülern im aktuellen Halbjahr eingetragen oder entfernt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Stundentafeln_zuweisen_(Gruppenprozesse_F%C3%A4cher)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5342.</p>',21)])])}const f=n(i,[["render",u]]);export{c as __pageData,f as default};
